impl From<HistError> for ApiError {
    fn from(error: HistError) -> ApiError {
        let paths = match &error {
            HistError::Ambiguous { ids, .. } => ids.clone(),
            _ => Vec::new(),
        };
        ApiError {
            status: status_of(&error),
            reply: ErrorReply {
                error: error.to_string(),
                paths,
            },
        }
    }
}

